// Function Definition: Modularity & Task Isolation
int calculate_square(int num) {
    // Single, defined task logic
    return num * num;
}

// Code Reusability: Called multiple times
int val_a = 7;
int sq_a = calculate_square(val_a);

int val_b = 15;
int sq_b = calculate_square(val_b);

// Benefits: Logic centralization improves maintenance.
// (If squaring logic changes, only one definition updates.)
